def _new_job_id():
    return secrets.token_hex(8)


def _job_path(job_id):
    safe = re.sub(r"[^a-zA-Z0-9_-]", "", str(job_id))[:64]
    return _JOBS_DIR / ("%s.json" % safe)


def job_set(job_id, **fields):
    with _job_lock:
        j = _jobs.get(job_id) or {}
        # merge disk if missing in memory
        if not j:
            try:
                p = _job_path(job_id)
                if p.is_file():
                    j = json.loads(p.read_text(encoding="utf-8") or "{}")
            except Exception:
                j = {}
        j.update(fields)
        j["id"] = job_id
        j["updated_at"] = time.time()
        # normalize percent
        try:
            j["percent"] = max(0, min(100, int(float(j.get("percent") or 0))))
        except Exception:
            j["percent"] = 0
        _jobs[job_id] = j
        try:
            _job_path(job_id).write_text(json.dumps(j, ensure_ascii=False), encoding="utf-8")
        except Exception:
            pass
        return dict(j)


def job_get(job_id):
    with _job_lock:
        j = _jobs.get(job_id)
        if j:
            return dict(j)
        try:
            p = _job_path(job_id)
            if p.is_file():
                j = json.loads(p.read_text(encoding="utf-8") or "{}")
                _jobs[job_id] = j
                return dict(j)
        except Exception:
            pass
        return None


def start_job(name, target, *args, job_id=None, **kwargs):
    """Run work in a non-daemon thread so it keeps going after Mini App closes.
    Returns job_id. target may accept progress via kwargs if designed for it.
    """
    jid = job_id or _new_job_id()
    job_set(
        jid,
        id=jid,
        name=name,
        status="running",
        percent=0,
        message="Starting…",
        result=None,
        error=None,
        created_at=time.time(),
    )

    def runner():
        try:
            target(*args, **kwargs)
            cur = job_get(jid) or {}
            if cur.get("status") == "running":
                job_set(jid, status="done", percent=100, message=cur.get("message") or "Done")
        except Exception as e:
            print("job", name, "error", e)
            job_set(jid, status="error", percent=100, message=str(e)[:200], error=str(e)[:200])

    th = threading.Thread(target=runner, name="job-%s-%s" % (name, jid), daemon=False)
    th.start()
    return jid




def _html(name):
    path = ROOT / name
    try:
        if path.is_file():
            return path.read_text(encoding="utf-8")
    except Exception:
        pass
    if name == "login.html":
        return base64.b64decode(_LOGIN_B64).decode("utf-8")
    if name == "dashboard.html":
        return base64.b64decode(_DASH_B64).decode("utf-8")
    return "<h1>Not found</h1>"


