@flask_app.route("/api/cpm_login", methods=["POST"])
def api_cpm_login():
    body = request.get_json(silent=True) or {}
    tg_id, _ = resolve_tg(body)
    if not tg_id:
        return jsonify({"ok": False, "error": "Open from Telegram bot → Open App"}), 401
    email = (body.get("email") or "").strip()
    password = body.get("password") or ""
    try:
        from cpm1_core import nuker
        lr = nuker.login(email, password)
        if not lr.get("ok"):
            return jsonify({"ok": False, "error": lr.get("message", "login_failed")})
        uid_key = abs(hash("web_%s" % tg_id)) % (10**9)
        nuker.save_token(uid_key, lr["auth"], email, password, lr.get("refresh_token", ""), lr.get("firebase_uid", ""))
        if not nuker.load(uid_key, force=True):
            # New / empty CPM profile — seed blank so tools can load
            seed = nuker.seed_blank_profile(lr["auth"], lr.get("firebase_uid", ""), email)
            nuker.save_token(uid_key, lr["auth"], email, password, lr.get("refresh_token", ""), lr.get("firebase_uid", ""))
            if not nuker.load(uid_key, force=True) and seed.get("ok"):
                nuker.set_record(uid_key, {
                    "Name": "Player", "money": 25000, "coin": 0,
                    "localID": seed.get("localID") or "00000001",
                    "allData": '{"cars":[]}',
                }, email)
        _cpm_sessions[tg_id] = {"email": email, "password": password, "auth": lr["auth"], "fuid": lr.get("firebase_uid", ""), "uid_key": uid_key}
        return jsonify({"ok": True, "email": email})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)[:120]})


@flask_app.route("/api/cpm_register", methods=["POST"])
def api_cpm_register():
    body = request.get_json(silent=True) or {}
    tg_id, _ = resolve_tg(body)
    if not tg_id:
        return jsonify({"ok": False, "error": "Open from Telegram bot → Open App"}), 401
    email = (body.get("email") or "").strip()
    password = body.get("password") or ""
    if not email or "@" not in email:
        return jsonify({"ok": False, "error": "Enter a valid email"})
    if len(password) < 6:
        return jsonify({"ok": False, "error": "Password min 6 chars"})
    try:
        from cpm1_core import nuker
        lr = nuker.register(email, password)
        if not lr.get("ok"):
            # if email already exists, try login path
            msg = str(lr.get("message") or "")
            if "EMAIL_EXISTS" in msg.upper():
                return jsonify({"ok": False, "error": "Email already used — switch to Login"})
            return jsonify({"ok": False, "error": lr.get("message", "register_failed")})
        # Prefer fresh login tokens
        lr2 = nuker.login(email, password)
        if lr2.get("ok"):
            lr = lr2
        auth = lr.get("auth") or ""
        fuid = lr.get("firebase_uid") or ""
        if not auth or not fuid:
            return jsonify({"ok": False, "error": "Register OK but missing token — try Login"})
        # Seed CPM player profile so load() works (new Firebase accounts have no CPM record yet)
        seed = nuker.seed_blank_profile(auth, fuid, email)
        if not seed.get("ok"):
            # one more login + seed
            lr3 = nuker.login(email, password)
            if lr3.get("ok"):
                auth = lr3.get("auth") or auth
                fuid = lr3.get("firebase_uid") or fuid
                lr = lr3
                seed = nuker.seed_blank_profile(auth, fuid, email)
        uid_key = abs(hash("web_%s" % tg_id)) % (10**9)
        nuker.save_token(
            uid_key, auth, email, password,
            lr.get("refresh_token", ""), fuid,
        )
        # Try load; if still empty, cache the blank so tools don't crash
        loaded = nuker.load(uid_key, force=True)
        if not loaded:
            blank_cache = {
                "Name": "Player",
                "money": 25000,
                "coin": 0,
                "localID": seed.get("localID") or "00000001",
                "allData": '{"cars":[]}',
                "floats": [0.0] * 50,
                "integers": [0] * 120,
            }
            nuker.set_record(uid_key, blank_cache, email)
        _cpm_sessions[tg_id] = {
            "email": email,
            "password": password,
            "auth": auth,
            "fuid": fuid,
            "uid_key": uid_key,
        }
        note = "Account created"
        if seed.get("ok"):
            note = "Account created + profile ready"
        else:
            note = "Account created (profile seed pending — open game once, then re-login)"
        return jsonify({"ok": True, "email": email, "message": note, "seed": seed.get("ok", False)})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)[:160]})



