def _send_tg(tg_id, text):
    if not bot:
        return
    try:
        text = str(text)
        while text:
            bot.send_message(int(tg_id), text[:3500], parse_mode="HTML")
            text = text[3500:]
    except Exception as e:
        print("send_tg", e)



@flask_app.route("/api/job/<job_id>")
def api_job_status(job_id):
    j = job_get(job_id)
    if not j:
        return jsonify({"ok": False, "error": "job_not_found"}), 404
    try:
        pct = int(float(j.get("percent") or 0))
    except Exception:
        pct = 0
    done = j.get("done")
    total = j.get("total")
    if (not pct) and done is not None and total:
        try:
            pct = int(100 * int(done) / max(1, int(total)))
        except Exception:
            pass
    pct = max(0, min(100, pct))
    return jsonify({
        "ok": True,
        "id": j.get("id"),
        "name": j.get("name"),
        "status": j.get("status"),
        "percent": pct,
        "done": done,
        "total": total,
        "message": j.get("message") or "",
        "error": j.get("error"),
        "result": j.get("result"),
    })



