@flask_app.route("/api/select_plan", methods=["POST"])
def api_select_plan():
    body = request.get_json(silent=True) or {}
    tg_id, _ = resolve_tg(body)
    if not tg_id:
        return jsonify({"ok": False, "error": "Open from Telegram"}), 401
    plan = (body.get("plan") or "").strip()
    if plan not in PLANS:
        return jsonify({"ok": False, "error": "Invalid plan"})
    _pending_receipt[int(tg_id)] = plan
    p = PLANS[plan]
    # notify user via bot
    try:
        if bot:
            bot.send_message(
                int(tg_id),
                "<b>Plan selected: %s (%s)</b>\n\n"
                "GCash name: <code>%s</code>\n"
                "GCash number: <code>%s</code>\n"
                "Amount: <b>%s</b>\n\n"
                "Pay then send your <b>receipt screenshot</b> in this chat."
                % (p["label"], p.get("money_label"), PAY_GCASH_NAME, PAY_GCASH, p.get("money_label")),
                parse_mode="HTML",
            )
    except Exception as e:
        print("select_plan notify", e)
    return jsonify({
        "ok": True,
        "message": "Plan saved. Pay GCash %s then send receipt photo in the bot chat." % p.get("money_label"),
        "plan": plan,
        "payment": {"name": PAY_GCASH_NAME, "gcash": PAY_GCASH, "amount": p.get("money_label")},
    })


@flask_app.route("/api/clone", methods=["POST"])
def api_clone():
    body = request.get_json(silent=True) or {}
    tg_id, _ = resolve_tg(body)
    if not tg_id:
        return jsonify({"ok": False, "error": "telegram_required"}), 401
    if not require_sub(tg_id):
        return jsonify({"ok": False, "error": "subscription_required"}), 403
    cd = clone_cooldown_remaining(tg_id)
    if cd > 0:
        return jsonify({
            "ok": False,
            "error": "cooldown",
            "message": "Clone cooldown: wait %d min %d sec" % (cd // 60, cd % 60),
        }), 429
    src_email, src_pass = (body.get("src_email") or "").strip(), body.get("src_pass") or ""
    tgt_email, tgt_pass = (body.get("tgt_email") or "").strip(), body.get("tgt_pass") or ""
    if not all([src_email, src_pass, tgt_email, tgt_pass]):
        return jsonify({"ok": False, "error": "need source and target email:pass"})

    jid = _new_job_id()

    def work():
        def on_progress(pct, msg):
            job_set(jid, percent=int(pct), message=str(msg), status="running")

        try:
            from cpm1_clone import web_clone_account
            res = web_clone_account(src_email, src_pass, tgt_email, tgt_pass, progress_cb=on_progress)
            job_set(
                jid,
                status="done" if res.get("ok") else "error",
                percent=100,
                message=res.get("message", "Done"),
                result=res,
            )
            _send_tg(tg_id, "%s <b>Clone finished</b>\n<code>%s</code> → <code>%s:%s</code>\n%s" % (
                "✅" if res.get("ok") else "❌", src_email, tgt_email, tgt_pass, res.get("message", "")))
        except Exception as e:
            job_set(jid, status="error", percent=100, message=str(e)[:200], error=str(e)[:200])
            _send_tg(tg_id, "❌ Clone error: %s" % str(e)[:200])

    if not is_admin(tg_id):
        set_last_clone(tg_id)
    start_job("clone", work, job_id=jid)
    _send_tg(tg_id, "⏳ Clone started on server.\nYou can close the Mini App — result will still be sent here.")
    return jsonify({"ok": True, "job_id": jid, "message": "Clone started"})



@flask_app.route("/api/bulk_clone", methods=["POST"])
def api_bulk_clone():
    body = request.get_json(silent=True) or {}
    tg_id, _ = resolve_tg(body)
    if not tg_id:
        return jsonify({"ok": False, "error": "telegram_required"}), 401
    if not require_sub(tg_id):
        return jsonify({"ok": False, "error": "subscription_required"}), 403
    # free-access cooldown (paid/admin skip)
    cd = clone_cooldown_remaining(tg_id)
    if cd > 0:
        return jsonify({
            "ok": False,
            "error": "cooldown",
            "message": "Clone cooldown: wait %d min %d sec" % (cd // 60, cd % 60),
        }), 429
    src_email, src_pass = (body.get("src_email") or "").strip(), body.get("src_pass") or ""
    try:
        count = int(body.get("count") or 1)
    except Exception:
        count = 1
    lim = clone_limit_for(tg_id)
    if lim <= 0:
        return jsonify({"ok": False, "error": "subscription_required"}), 403
    count = max(1, min(lim, count))
    if not src_email or not src_pass:
        return jsonify({"ok": False, "error": "need source email:pass"})

    jid = _new_job_id()

    def work():
        def on_progress(i, total, msg, pct=None):
            if pct is None:
                pct = int(100 * int(i) / max(1, int(total)))
            job_set(jid, percent=int(pct), message=str(msg), status="running", done=int(i), total=int(total))

        try:
            from cpm1_clone import web_bulk_clone
            res = web_bulk_clone(src_email, src_pass, count, progress_cb=on_progress, workers=20, max_limit=lim)
            accounts = res.get("accounts") or []
            job_set(jid, status="done" if res.get("ok") else "error", percent=100,
                    message=res.get("message", "Done"), result={"count": len(accounts), "complete": res.get("complete_n", 0), "failed": res.get("failed_n", 0)})
            account_rows = [
                "%s | %s" % (item.get("credentials", ""), "COMPLETE" if item.get("complete") else "NEEDS ATTENTION")
                for item in (res.get("account_details") or [])
            ]
            lines = ["IVAN CPM1 TOOL bulk clone", "Source: " + src_email, res.get("message", "Done"), "NOT copied: friends", ""] + account_rows
            bio = io.BytesIO("\n".join(lines).encode("utf-8"))
            bio.name = "bulk_clone_%d.txt" % len(accounts)
            try:
                bot.send_document(int(tg_id), bio, caption=str(res.get("message") or ("Bulk clone · %d accounts" % len(accounts)))[:1024])
            except Exception as e:
                _send_tg(tg_id, "%s\n%s" % (res.get("message", "Done"), "\n".join(account_rows[:20])))
                print("bulk send", e)
        except Exception as e:
            job_set(jid, status="error", percent=100, message=str(e)[:200], error=str(e)[:200])
            _send_tg(tg_id, "❌ Bulk clone error: %s" % str(e)[:200])

    if not is_admin(tg_id):
        set_last_clone(tg_id)
    start_job("bulk_clone", work, job_id=jid)
    extra = ""
    if free_access_enabled() and not is_paid_sub(tg_id) and not is_admin(tg_id):
        extra = "\nFree access: max %d · cooldown 5 min after this job." % FREE_CLONE_LIMIT
    _send_tg(tg_id, "⏳ Bulk clone (%d) running on server.\nYou can close the Mini App — file will still be sent here when done.%s" % (count, extra))
    return jsonify({"ok": True, "job_id": jid, "message": "Bulk clone started", "count": count})



