    @bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("approve_"))
    def cb_approve(call):
        if not is_admin(call.from_user.id):
            bot.answer_callback_query(call.id, "Admin only")
            return
        # approve_<tg_id>_<plan>
        parts = call.data.split("_")
        if len(parts) < 3:
            bot.answer_callback_query(call.id, "Bad data")
            return
        try:
            tid = int(parts[1])
        except Exception:
            bot.answer_callback_query(call.id, "Bad id")
            return
        plan = "_".join(parts[2:])
        # handle 7days etc - plan is after second underscore joined... approve_123_7days
        # actually format approve_{tid}_{plan_key}
        rest = call.data[len("approve_"):]
        try:
            tid_s, plan = rest.split("_", 1)
            tid = int(tid_s)
        except Exception:
            bot.answer_callback_query(call.id, "Bad data")
            return
        if plan not in PLANS:
            bot.answer_callback_query(call.id, "Invalid plan")
            return
        upsert_user(tid)
        set_subscription(tid, plan)
        st = sub_status(tid)
        bot.answer_callback_query(call.id, "Activated")
        try:
            bot.edit_message_reply_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        except Exception:
            pass
        bot.send_message(call.message.chat.id, "✅ Activated <b>%s</b> for <code>%s</code> until %s" % (PLANS[plan]["label"], tid, st.get("expires_str")))
