    @bot.message_handler(commands=["broadcast"])
    def cmd_broadcast(message):
        if not is_admin(message.from_user.id):
            bot.reply_to(message, "Admin only.")
            return
        text = (message.text or "")
        # /broadcast message...
        parts = text.split(None, 1)
        if len(parts) < 2 or not parts[1].strip():
            bot.reply_to(
                message,
                "Usage:\n<code>/broadcast Your message here</code>\n\n"
                "Sends to all users in the database.",
                parse_mode="HTML",
            )
            return
        payload = parts[1].strip()
        with db() as c:
            rows = c.execute("SELECT tg_id FROM users").fetchall()
        ids = [int(r["tg_id"]) for r in rows if r["tg_id"]]
        bot.reply_to(message, "📢 Broadcasting to %d users…" % len(ids))

        def _run():
            ok = fail = 0
            body = "📢 <b>Announcement</b>\n\n" + payload
            for tid in ids:
                try:
                    bot.send_message(tid, body, parse_mode="HTML")
                    ok += 1
                except Exception:
                    fail += 1
                time.sleep(0.05)
            try:
                bot.send_message(
                    message.chat.id,
                    "✅ Broadcast done\nSent: <b>%d</b>\nFailed: <b>%d</b>" % (ok, fail),
                    parse_mode="HTML",
                )
            except Exception:
                pass

        threading.Thread(target=_run, daemon=True).start()


